    "tanh"
  ],
  "implementation_hint": {
    "expects": {
      "batch": "dict with Tensor fields: log_prob_w, log_prob_l, cost_a, cost_b, optional weight",
      "model_output": "unused",
      "extra": "dict-like; may contain alpha (float or Tensor) and/or hyperparams dict"
    },
    "mode": "pairwise_preference"
  },
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    cost_a = batch['cost_a']
    cost_b = batch['cost_b']
    weight = batch.get('weight', None)

    # Use a tensor anchor to place scalar hyperparams/alpha on the right device/dtype.
    anchor = lpw

    hp = {}
    if isinstance(extra, dict):
        hp = extra.get('hyperparams', {}) if isinstance(extra.get('hyperparams', {}), dict) else {}

    def to_tensor(v, default):
        if v is None:
            v = default
        if isinstance(v, (int, float)):
            return anchor.new_tensor(v)
        return v

    alpha = anchor.new_tensor(1.0)
    if isinstance(extra, dict):
        alpha = to_tensor(extra.get('alpha', hp.get('alpha', 1.0)), 1.0)

    scale = to_tensor(hp.get('scale', 1.5), 1.5)
    cost_coef = to_tensor(hp.get('cost_coef', 0.055), 0.055)
    x_cap = to_tensor(hp.get('x_cap', 20.0), 20.0)
    alpha_cap = to_tensor(hp.get('alpha_cap', 5.0), 5.0)

    pref_margin = lpw - lpl
    cost_gap = cost_b - cost_a

    # Softly bound alpha and the decision logit to avoid extreme values while keeping gradients smooth.
    alpha_eff = alpha_cap * ops.tanh(alpha / alpha_cap)
    x_raw = alpha_eff * scale * pref_margin - cost_coef * ops.tanh(cost_gap)
    x = x_cap * ops.tanh(x_raw / x_cap)

    loss = -ops.logsigmoid(x)
    if weight is not None:
        loss = loss * weight
    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry / DPO-style) loss on log-probability differences. A bounded tanh(cost_b-cost_a) term incorporates relative cost without allowing cost outliers to dominate. The preference logit is softly capped via tanh to prevent numerical blow-ups while keeping gradients continuous. Alpha is softly bounded to improve robustness to extreme scheduling values without changing behavior near the typical alpha≈1 regime."
